-- Purano Dhun — festive seed for existing databases (generated).
-- Run AFTER 0007_festival_features.sql and 0008_festival_calendar.sql.
-- Idempotent: safe to re-run. Regenerate with
--   node supabase/tools/build_festive_upgrade.mjs

begin;

-- Festival artists (28-59)
on conflict (id) do nothing;

-- Festive songs (1001-1061)
on conflict (id) do nothing;

-- Tag songs with their festival
update public.songs
set festival_id = c.id
from (values
    (13, 1),   -- Malshree Dhun (Dashain) -> Dashain
    (12, 3),   -- Chari Jailaima -> Teej
    (139, 2)   -- Jai Mata Laxmi -> Tihar
) as mapping(song_id, festival_id)
join public.festival_categories c on c.id = mapping.festival_id
where public.songs.id = mapping.song_id;

update public.songs
